import { fileURLToPath } from 'node:url';
import { drizzle } from 'drizzle-orm/postgres-js';
import { migrate } from 'drizzle-orm/postgres-js/migrator';
import postgres from 'postgres';

/**
 * The committed SQL migrations, generated by `vp run db:generate` from the web app's
 * Drizzle schema. Resolved from this module's location so it works from any cwd.
 */
export const MIGRATIONS_FOLDER = fileURLToPath(new URL('../migrations', import.meta.url));

/**
 * Applies all pending migrations to the database at `databaseUrl`. Already applied
 * migrations are skipped, so running it again is a no-op. Uses a single dedicated
 * connection that is always closed, so the one-shot process can exit promptly.
 */
export async function runMigrations(
  databaseUrl: string,
  migrationsFolder: string = MIGRATIONS_FOLDER,
): Promise<void> {
  // Notices (e.g. "schema already exists, skipping") are expected noise here.
  const sql = postgres(databaseUrl, { max: 1, onnotice: () => {} });

  try {
    await migrate(drizzle(sql), { migrationsFolder });
  } finally {
    await sql.end({ timeout: 5 });
  }
}
